// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(uint256 startBlock, address actor, bytes32 h1, bytes32 h2) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        uint256 b = bound(startBlock, 1, 1_000_000);

        // lock a first guess at a fuzzed block
        vm.roll(b);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h1);

        // advance past the guess block so settle() is admissible
        vm.roll(b + 2);
        vm.prank(actor);
        c.settle();

        // RULE: once a guess has been settled, the slot is cleared and the same
        // actor can lock a new guess immediately.
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        bool ok;
        try c.lockInGuess{value: 1 ether}(h2) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "settled actor must be able to lock a new guess");
    }
}
